const dot = (a: number[], b: number[]) => a.reduce((s, x, i) => s + x * b[i], 0)
const cosine = (a: number[], b: number[]) =>
  dot(a, b) / Math.sqrt(dot(a, a) * dot(b, b))

type Chunk = { text: string; vector: number[] }

function topK(query: number[], chunks: Chunk[], k = 3) {
  return chunks
    .map((c) => ({ ...c, score: cosine(query, c.vector) }))
    .sort((a, b) => b.score - a.score)
    .slice(0, k)
}

const cases = [
